import { defineConfig } from 'orval';

/**
 * Typed API client generated from the backend contract (../api/openapi.json).
 * Run `pnpm gen:api` after the API changes; never edit src/core/api/generated by hand.
 */
export default defineConfig({
  bocardo: {
    input: {
      target: '../api/openapi.json',
      // only the endpoints this app uses
      filters: { tags: ['users', 'partner', 'feedback'] },
    },
    output: {
      mode: 'tags-split',
      target: 'src/core/api/generated',
      schemas: 'src/core/api/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      clean: true,
      override: {
        mutator: { path: 'src/core/api/http-client.ts', name: 'httpClient' },
        fetch: { includeHttpResponseReturnType: false },
        query: { signal: true },
      },
    },
  },
});
